mapper.select:
select * from (
select DM.dm_message_no as no, DM.dm_room_no as room_no, DM.dm_message_sender_no as sender_no, E.emp_name as sender_name, DM.dm_message_content as content, DM.dm_message_ctime as ctime
from dm_message DM
left outer join emp E on DM.dm_message_sender_no = E.emp_no
where DM.dm_room_no = #{roomNo}
and DM.dm_message_no < #{lastMessageNo}
order by DM.dm_message_no desc
)
where rownum <= #{size}
order by no asc


select count(*)

from dm_message

where dm_room_no = #{roomNo}



		and dm_message_no < #{lastMessageNo}
